/**
 * The recorded breathing-voice lines: line id ('<group>/<id>' in scripts/tts-script.json) to its
 * file, relative to assets/audio/breathwork/.
 *
 * Generated by scripts/index-breathwork-voices.mjs (npm run tts:index) from the files in
 * public/assets/audio/breathwork/voices. Do not edit by hand: scripts/generate-tts.js rewrites it
 * after recording. The game never requests a line missing from this list, so a line that is
 * written but not recorded (or whose words changed since it was recorded) is shown on screen.
 */
export const RECORDED_VOICES = Object.freeze({
    'cues/breathe_in': 'voices/cues/breathe_in.wav',
    'cues/breathe_in_soft': 'voices/cues/breathe_in_soft.wav',
    'cues/breathe_out': 'voices/cues/breathe_out.wav',
    'cues/breathe_out_soft': 'voices/cues/breathe_out_soft.wav',
    'cues/hold_gently': 'voices/cues/hold_gently.wav',
    'cues/in_quick': 'voices/cues/in_quick.wav',
    'cues/out_quick': 'voices/cues/out_quick.wav',
    'cues/slow_exhale': 'voices/cues/slow_exhale.wav',
    'encouragement/doing_well': 'voices/encouragement/doing_well.wav',
    'encouragement/proud': 'voices/encouragement/proud.wav',
    'encouragement/thank_yourself': 'voices/encouragement/thank_yourself.wav',
    'fillers/complete_whole': 'voices/fillers/complete_whole.wav',
    'fillers/nothing_to_do': 'voices/fillers/nothing_to_do.wav',
    'fillers/stay_here': 'voices/fillers/stay_here.wav',
    'fillers/you_are_safe': 'voices/fillers/you_are_safe.wav',
    'intentions/base_breathe': 'voices/intentions/base_breathe.wav',
    'intentions/base_calm': 'voices/intentions/base_calm.wav',
    'intentions/base_ground': 'voices/intentions/base_ground.wav',
    'intentions/elixir_release': 'voices/intentions/elixir_release.wav',
    'intentions/flow_rhythm': 'voices/intentions/flow_rhythm.wav',
});

/** @param {string} id e.g. 'cues/hold' @returns {string|null} e.g. 'voices/cues/hold.mp3' */
export function recordedVoiceFile(id) {
    return Object.prototype.hasOwnProperty.call(RECORDED_VOICES, id) ? RECORDED_VOICES[id] : null;
}
